import {clsx} from 'clsx'
import {Button, Link} from '@primer/react'
import {useTheme} from '@primer/styled-react'
import {CopilotIcon} from '@primer/octicons-react'
import {openSecurityAssessmentCopilotChat} from '../utils/copilot-chat-helpers'

export interface RiskAssessmentBannerProps {
  title: string
  description: string
  descriptionMaxWidth?: number
  isLoading: boolean
  primaryAction: {
    onClick: () => void
    label: string
  }
  secondaryAction: {
    href: string
    onClick?: () => void
    label: string
  }
  images: {
    day: string
    night: string
  }
  analyticsVisible?: Record<string, string>
  showCopilotAssist?: boolean
  className?: string
}

export function RiskAssessmentBanner({
  title,
  description,
  descriptionMaxWidth = 400,
  primaryAction,
  secondaryAction,
  images,
  isLoading,
  analyticsVisible,
  showCopilotAssist = false,
  className,
}: RiskAssessmentBannerProps) {
  const {resolvedColorMode} = useTheme()

  return (
    <div
      className={clsx('organization-ipm-banner', className)}
      data-analytics-visible={analyticsVisible ? JSON.stringify(analyticsVisible) : undefined}
    >
      <div className="organization-ipm-banner-content">
        <h2 data-hpc className="h2 my-1">
          {title}
        </h2>

        <p className="color-fg-muted mb-0" style={{maxWidth: descriptionMaxWidth}}>
          {description}
        </p>

        <div className="organization-ipm-banner-actions">
          <Button
            variant="primary"
            onClick={primaryAction.onClick}
            loading={isLoading}
            className="d-inline-flex flex-items-center gap-1"
          >
            {primaryAction.label}
          </Button>
          {showCopilotAssist ? (
            <Button
              leadingVisual={CopilotIcon}
              onClick={() => {
                openSecurityAssessmentCopilotChat()
              }}
            >
              Ask Copilot
            </Button>
          ) : (
            <Link href={secondaryAction.href} onClick={secondaryAction.onClick}>
              {secondaryAction.label}
            </Link>
          )}
        </div>
      </div>

      <div className="organization-ipm-banner-image-container">
        <img
          className="security-secret-leaks-promo-banner-image-el"
          src={resolvedColorMode === 'night' ? images.night : images.day}
          alt=""
          width={440}
          height={208}
        />
      </div>
    </div>
  )
}
