import {useState} from 'react'
import {clsx} from 'clsx'
import DataCard from '@github-ui/data-card'
import {useQuery} from '@github-ui/react-query'
import {AnchoredOverlay, Banner, Button, IconButton, Label, Link, RelativeTime} from '@primer/react'
import {DataTable, Table} from '@primer/react/experimental'
import {AlertIcon, InfoIcon, XIcon} from '@primer/octicons-react'
import Pluralize from 'pluralize'
import {useTheme} from '@primer/styled-react'

import {queries} from '../api'
import type {CsraAssessment, Org, RepositoryResult} from '../types'
import styles from './CodeSecurityAssessmentResultPage.module.css'
import {EnablementDialog} from './EnablementDialog'

const LANGUAGE_COLORS = [
  'var(--bgColor-success-emphasis)',
  'var(--bgColor-accent-emphasis)',
  'var(--bgColor-done-emphasis)',
]

function languageColor(index: number) {
  return LANGUAGE_COLORS[index % LANGUAGE_COLORS.length]
}

function isRepoFailed(status: string): boolean {
  return status === 'failed' || status === 'timed_out'
}

interface CodeSecurityAssessmentResultPageProps {
  org: Org
  refetchInterval?: number
}

const SEVERITY_VARIANT: Record<
  NonNullable<CsraAssessment['top_rules'][number]['severity']>,
  'danger' | 'severe' | 'attention' | 'default'
> = {
  critical: 'danger',
  high: 'severe',
  medium: 'attention',
  low: 'default',
}

const MAX_POLLING_RETRIES = 3

const REPOS_PAGE_SIZE = 5

const REPOSITORY_SKELETON_COLUMNS = [{header: 'Repository'}, {header: 'Autofix vulnerabilities'}, {header: ''}]
const TOP_RULES_SKELETON_COLUMNS = [
  {header: 'Rule'},
  {header: 'Rule severity'},
  {header: 'Distinct repositories'},
  {header: 'Vulnerabilities found'},
]

export function CodeSecurityAssessmentResultPage({org, refetchInterval = 5000}: CodeSecurityAssessmentResultPageProps) {
  const [repoPageIndex, setRepoPageIndex] = useState(0)
  const [isDialogOpen, setIsDialogOpen] = useState(false)

  const {data, isError} = useQuery({
    ...queries.csraAssessment(org.login),
    staleTime: Infinity,
    refetchInterval: query => {
      if (query.state.errorUpdateCount >= MAX_POLLING_RETRIES) return false
      const assessment = query.state.data
      if (assessment?.status === 'completed' || assessment?.status === 'failed') return false
      return refetchInterval
    },
  })

  const isLoading = !data || data.status === 'pending'
  const isAssessmentFailed = data?.status === 'failed'
  const noVulnerabilitiesFound = data?.status === 'completed' && data.total_vulnerabilities === 0
  const hasPollingFailed = isError && isLoading

  const autofixCount = data ? data.repositories_scanned.reduce((sum, repo) => sum + repo.autofix_count, 0) : 0
  const successfulRepoCount = data ? data.repositories_scanned.filter(r => !isRepoFailed(r.status)).length : 0

  const mostVulnerableRepo = data?.repositories_scanned
    .filter(r => !isRepoFailed(r.status))
    .reduce<RepositoryResult | null>((max, repo) => {
      if (!max || repo.total_vulnerability_count > max.total_vulnerability_count) return repo
      return max
    }, null)

  const allRepos = data?.repositories_scanned ?? []
  const paginatedRepos = allRepos
    .slice(repoPageIndex * REPOS_PAGE_SIZE, (repoPageIndex + 1) * REPOS_PAGE_SIZE)
    .map(repo => ({...repo, id: repo.name}))

  const totalVulns = data?.total_vulnerabilities ?? 0
  const autofixPercentage = Math.round((autofixCount / totalVulns) * 100)
  const progressData = (data?.vulnerabilities_by_language ?? []).map((lang, index) => ({
    progress: totalVulns > 0 ? (lang.count / totalVulns) * 100 : 0,
    label: lang.language,
    color: languageColor(index),
  }))

  const showEnablementBanner = data?.status === 'completed' && totalVulns > 0

  return (
    <div className={styles.container} data-testid="code-security-assessment-result-page">
      {hasPollingFailed && (
        <Banner variant="critical" title="Something went wrong loading your assessment. Please try again later." />
      )}
      {data?.status === 'pending' && !hasPollingFailed && <Banner title="Scan in progress" variant="info" />}

      {noVulnerabilitiesFound && (
        <NoVulnerabilitiesBanner
          repoCount={data.total_selected_repositories}
          totalOrgRepos={data.total_org_repositories}
          onEnableClick={() => setIsDialogOpen(true)}
        />
      )}

      {showEnablementBanner && (
        <div className="d-flex flex-justify-between flex-items-center tmp-p-3 bgColor-accent-muted border rounded-2">
          <div>
            <p className="text-semibold mb-1">
              {autofixPercentage}% of vulnerabilities can be fixed automatically with Code Security
            </p>
            <p className="fgColor-muted f6 mb-0">
              Have questions about Code Security? {/* TODO: Replace with real contact link */}
              <Link inline href="#">
                Talk to someone at GitHub.
              </Link>
            </p>
          </div>
          <Button variant="primary" onClick={() => setIsDialogOpen(true)}>
            Enable Code Security
          </Button>
        </div>
      )}

      <EnablementDialog
        isOpen={isDialogOpen}
        onClose={() => setIsDialogOpen(false)}
        cost={{increased_license_usage: 0, per_license: '$0', total: '$0'}} // TODO: Wire up real cost data https://github.com/github/security-products-enablement/issues/2628
        org={org}
        handleEnablement={() => {}} // TODO: Wire up CSRA enablement handler https://github.com/github/security-products-enablement/issues/2604
        assessmentNumber={data?.number ?? 0}
        context="code-security"
      />

      {/* Row 1: Summary data cards */}
      <div className={styles.cardRow}>
        <DataCard
          className={styles.dataCard}
          data-testid="total-repos-card"
          cardTitle={
            <span className={styles.cardTitleWithInfo}>
              Total repositories scanned
              <InfoOverlay ariaLabel="Info about total repositories scanned">
                Code Security risk assessment is limited to 20 repositories, selected by the user.
              </InfoOverlay>
            </span>
          }
          loading={isLoading}
        >
          {!isLoading && (
            <>
              <DataCard.Counter
                count={isAssessmentFailed ? 0 : successfulRepoCount}
                total={data.total_selected_repositories}
              />
              {data.status === 'completed' && (
                <DataCard.Description>
                  Scan completed <RelativeTime datetime={data.created_at} />
                </DataCard.Description>
              )}
            </>
          )}
        </DataCard>
        <DataCard className={styles.dataCard} cardTitle="Total vulnerabilities found" loading={isLoading}>
          {!isLoading && (
            <>
              <DataCard.Counter count={isAssessmentFailed ? 0 : data.total_vulnerabilities} />
              <DataCard.Description>Vulnerabilities found with code scanning.</DataCard.Description>
            </>
          )}
        </DataCard>
        <DataCard
          className={styles.dataCard}
          cardTitle={
            <span className={styles.cardTitleWithInfo}>
              Copilot Autofix
              <InfoOverlay ariaLabel="Info about Copilot Autofix">
                GitHub uses AI to automatically suggest fixes for{' '}
                <Link
                  inline
                  href="https://docs.github.com/en/enterprise-cloud@latest/code-security/responsible-use/responsible-use-autofix-code-scanning"
                >
                  code scanning alerts detected by CodeQL
                </Link>
                , helping you resolve vulnerabilities faster without leaving your pull request workflow.
              </InfoOverlay>
            </span>
          }
          loading={isLoading}
        >
          {!isLoading && (
            <>
              <DataCard.Counter
                count={isAssessmentFailed ? 0 : autofixCount}
                total={isAssessmentFailed ? 0 : data.total_vulnerabilities}
              />
              <DataCard.Description>
                Critical code scanning alerts that are eligible for Copilot Autofix.
              </DataCard.Description>
            </>
          )}
        </DataCard>
      </div>

      {/* Row 2: Chart area cards */}
      {!noVulnerabilitiesFound && (
        <div className={styles.cardRow}>
          <DataCard className={styles.dataCard} cardTitle="Vulnerabilities by language" loading={isLoading}>
            {!isLoading && progressData.length > 0 ? (
              <>
                <DataCard.ProgressBar data={progressData} aria-label="Vulnerabilities by language" />
                <div className={styles.languageLegend}>
                  {data.vulnerabilities_by_language.map((lang, index) => (
                    <span key={lang.language} className={styles.legendItem}>
                      <span
                        className={styles.legendDot}
                        style={{backgroundColor: languageColor(index)}}
                        aria-hidden="true"
                      />
                      {lang.language} ({lang.count})
                    </span>
                  ))}
                </div>
                <DataCard.Description>
                  Breakdown of vulnerabilities by language covered in code scanning.
                </DataCard.Description>
              </>
            ) : (
              !isLoading && <DataCard.Description>—</DataCard.Description>
            )}
          </DataCard>
          <DataCard
            className={styles.dataCard}
            data-testid="most-vulnerable-repo-card"
            cardTitle="Most vulnerable repository"
            loading={isLoading}
          >
            {!isLoading && mostVulnerableRepo ? (
              <DataCard.Description className={styles.repoName}>{mostVulnerableRepo.name}</DataCard.Description>
            ) : (
              !isLoading && <DataCard.Description>—</DataCard.Description>
            )}
          </DataCard>
        </div>
      )}

      {/* Table 1: Repositories scanned */}
      {!isAssessmentFailed && !noVulnerabilitiesFound && (
        <div>
          <div className={styles.tableHeader}>
            <h3 className={styles.tableHeading}>Repositories scanned</h3>
          </div>
          <Table.Container>
            {isLoading ? (
              <Table.Skeleton
                aria-label="Repositories scan in progress"
                columns={REPOSITORY_SKELETON_COLUMNS}
                rows={5}
              />
            ) : (
              <>
                <DataTable
                  aria-label="Repositories scanned"
                  data={paginatedRepos}
                  columns={[
                    {
                      header: 'Repository',
                      field: 'name',
                    },
                    {
                      header: 'Autofix vulnerabilities',
                      id: 'autofix',
                      renderCell: repo =>
                        isRepoFailed(repo.status) ? (
                          <span>
                            <AlertIcon className="fgColor-attention mr-1" />
                            Failed to scan
                          </span>
                        ) : (
                          `${repo.autofix_count}/${repo.total_vulnerability_count}`
                        ),
                    },
                    {
                      header: '',
                      id: 'action',
                      renderCell: repo => (!isRepoFailed(repo.status) ? <Link href="#">Enable</Link> : null),
                    },
                  ]}
                />
                {allRepos.length > REPOS_PAGE_SIZE && (
                  <Table.Pagination
                    aria-label="Pagination for repositories scanned"
                    totalCount={allRepos.length}
                    pageSize={REPOS_PAGE_SIZE}
                    onChange={({pageIndex}) => setRepoPageIndex(pageIndex)}
                  />
                )}
              </>
            )}
          </Table.Container>
        </div>
      )}

      {/* Table 2: Top rules */}
      {!isAssessmentFailed && !noVulnerabilitiesFound && (
        <div>
          <div className={styles.tableHeader}>
            <h3 className={styles.tableHeading}>Top rules</h3>
          </div>
          <Table.Container>
            {isLoading ? (
              <Table.Skeleton
                aria-label="Vulnerability scan in progress"
                columns={TOP_RULES_SKELETON_COLUMNS}
                rows={5}
              />
            ) : (
              <DataTable
                aria-label="Top rules"
                data={data.top_rules.map(rule => ({...rule, id: rule.rule_id}))}
                columns={[
                  {
                    header: 'Rule',
                    id: 'rule_name',
                    renderCell: rule => rule.rule_name ?? 'Unknown rule',
                  },
                  {
                    header: 'Rule severity',
                    id: 'severity',
                    renderCell: rule =>
                      rule.severity ? (
                        <Label variant={SEVERITY_VARIANT[rule.severity]}>
                          {rule.severity.charAt(0).toUpperCase() + rule.severity.slice(1)}
                        </Label>
                      ) : (
                        '—'
                      ),
                  },
                  {
                    header: 'Distinct repositories',
                    field: 'distinct_repos',
                    align: 'end',
                  },
                  {
                    header: 'Vulnerabilities found',
                    field: 'total_vulnerabilities',
                    align: 'end',
                    sortBy: true,
                  },
                ]}
                initialSortColumn="total_vulnerabilities"
                initialSortDirection="DESC"
              />
            )}
          </Table.Container>
        </div>
      )}
    </div>
  )
}

function InfoOverlay({ariaLabel, children}: {ariaLabel: string; children: React.ReactNode}) {
  const [isOpen, setIsOpen] = useState(false)
  return (
    <AnchoredOverlay
      className="tmp-p-4"
      align="center"
      width="medium"
      open={isOpen}
      onOpen={() => setIsOpen(true)}
      onClose={() => setIsOpen(false)}
      renderAnchor={props => (
        <IconButton {...props} variant="invisible" icon={InfoIcon} aria-label={ariaLabel} aria-labelledby={undefined} />
      )}
    >
      <p>{children}</p>
    </AnchoredOverlay>
  )
}

function NoVulnerabilitiesBanner({
  repoCount,
  totalOrgRepos,
  onEnableClick,
}: {
  repoCount: number
  totalOrgRepos: number
  onEnableClick: () => void
}) {
  const [isOpen, setIsOpen] = useState(true)
  const {resolvedColorMode} = useTheme()
  const color = resolvedColorMode === 'night' ? 'night' : 'day'

  if (!isOpen) return null

  return (
    <div className="position-relative d-flex flex-justify-between gap-4 tmp-p-4 tmp-mb-3 bgColor-muted border rounded-2">
      <IconButton
        className="position-absolute top-0 right-0 mt-2 mr-2"
        variant="invisible"
        icon={XIcon}
        aria-label="Dismiss banner"
        onClick={() => setIsOpen(false)}
      />
      <div className="d-flex flex-column flex-justify-between" style={{maxWidth: '55%'}}>
        <h2 className="h3">
          Great work! No vulnerabilities found in {repoCount} {Pluralize('repository', repoCount)}
        </h2>
        <p className="tmp-mb-3 fgColor-muted f5">
          This assessment scanned {repoCount} of your {totalOrgRepos} repositories. Enable Code Security to prevent
          vulnerabilities in your organization.
        </p>
        <div className="d-flex flex-items-center gap-3">
          <Button variant="primary" onClick={onEnableClick}>
            Enable Code Security
          </Button>
          <Link href="#">Learn more</Link>
        </div>
      </div>
      <img
        className={clsx(styles.bannerImage, 'tmp-mt-3 tmp-mr-n4 tmp-mb-n4')}
        src={`/images/secret-scanning/risk-assessment/no_leaks_banner--${color}.png`}
        alt=""
      />
    </div>
  )
}
