export function riskAssessmentPath(org: string) {
  return `/orgs/${org}/security/assessments`
}

export function riskAssessmentJsonPath(org: string) {
  return `/orgs/${org}/security/assessments/json`
}

export function downloadResultsCSVPath(org: string, number?: number) {
  return number
    ? `/orgs/${org}/security/assessments/${number}/results-csv.csv`
    : `/orgs/${org}/security/assessments/results-csv.csv`
}

export function enableGhspPath(org: string) {
  return `/orgs/${org}/security/assessments/enable-ghsp`
}

export function enableGhspOnSelectedReposPath(org: string) {
  return `/orgs/${org}/security/assessments/enable-ghsp-on-selected-repos`
}

export function hasConfigConflict(org: string) {
  return `/orgs/${org}/security/assessments/has-config-conflict`
}

export function allReposEnabledPath(org: string) {
  return `/orgs/${org}/security/assessments/all-repos-enabled`
}

export function fetchReposPath(org: string, number: number) {
  return `/orgs/${org}/security/assessments/${number}/repositories`
}

export function riskAssessmentShowPath(org: string, assessmentNumber: number) {
  return `/orgs/${org}/security/assessments/${assessmentNumber}`
}

export function riskAssessmentScanRepositoriesPath(org: string, query?: string) {
  const basePath = `/orgs/${org}/security/assessments/repositories/scan`
  if (query) {
    const params = new URLSearchParams()
    params.set('q', query)
    return `${basePath}?${params.toString()}`
  }
  return basePath
}

export function csraJsonPath(org: string) {
  return `/orgs/${org}/security/assessments/csra-json`
}

export function csraReposPath(org: string, query?: string) {
  const basePath = `/orgs/${org}/security/assessments/repositories/csra`
  if (query) {
    const params = new URLSearchParams()
    params.set('q', query)
    return `${basePath}?${params.toString()}`
  }
  return basePath
}

export function riskAssessmentEligibilityPath(org: string) {
  return `/orgs/${org}/security/assessments/eligibility`
}
