import {type RepoSelection, RepositorySelectionGroup} from './RepositorySelectionGroup'
import type {Cost, EnablementDialogContext, Org} from '../../types'
import {CostSummaryBox} from './CostSummaryBox'
import {Banner} from '@primer/react'
import {getCostDisplayValues} from './enablement-dialog-utils'

interface CostEstimationProps {
  additionalCost: string
  repoSelection: RepoSelection
  onRepoSelectionChange: (selection: RepoSelection) => void
  cost: Cost
  selectedReposCount: number
  selectedLicenseCount: number
  isEnterpriseOrMT?: boolean
  org: Org
  context: EnablementDialogContext
  productName: string
}

export function CostEstimation({
  additionalCost,
  repoSelection,
  selectedReposCount,
  onRepoSelectionChange,
  cost,
  selectedLicenseCount,
  isEnterpriseOrMT = false,
  org,
  context,
  productName,
}: CostEstimationProps) {
  const isSecretProtection = context === 'secret-protection'

  const {licenseCount, repositoryCountText, perLicenseCost} = getCostDisplayValues(
    repoSelection,
    cost,
    selectedLicenseCount,
    selectedReposCount,
  )

  const isOnSecretProtectionTrial = org.active_ghas_trials?.includes('secret_protection_trial')
  const trialExpirationDate = org.active_ghas_trials_expiration?.secret_protection_trial

  return (
    <>
      {isSecretProtection && isOnSecretProtectionTrial && trialExpirationDate && (
        <Banner
          title="Info"
          hideTitle
          description={`You are currently on a GitHub Secret Protection trial until ${trialExpirationDate}. No charges will be incurred during that trial.`}
          className="tmp-mb-3"
        />
      )}
      <p>
        <span>{productName} is </span>
        {!isEnterpriseOrMT && <span>free for public repositories and </span>}
        <span>billed per active committer for private repositories.</span>
      </p>
      {isSecretProtection && <p>Estimate your monthly cost based on selection.</p>}
      {!isSecretProtection && <p>Enable in:</p>}

      <RepositorySelectionGroup value={repoSelection} onChange={onRepoSelectionChange} />

      {isSecretProtection && (
        <CostSummaryBox
          additionalCost={additionalCost}
          licenseCount={licenseCount}
          repositoryCountText={repositoryCountText}
          perLicenseCost={perLicenseCost}
          productName={productName}
        />
      )}
    </>
  )
}
