import Pluralize from 'pluralize'

interface CostSummaryBoxProps {
  additionalCost: string
  licenseCount: number
  repositoryCountText: string
  perLicenseCost: string
  variant?: 'default' | 'review'
  productName: string
}

export function CostSummaryBox({
  additionalCost,
  licenseCount,
  repositoryCountText,
  perLicenseCost,
  variant = 'default',
  productName,
}: CostSummaryBoxProps) {
  return (
    <div className={`${variant === 'review' ? 'mb-2 tmp-p-4' : 'tmp-p-3'} bgColor-muted rounded-2`}>
      <span className="fgColor-muted">Additional estimated cost for your organization</span>
      <p>
        <span className="text-bold">{additionalCost}</span> <span className="fgColor-muted">/ month</span>
      </p>
      <hr />
      <p className="mb-0">{`${Pluralize(
        `${productName} license`,
        licenseCount,
        true,
      )} across ${repositoryCountText}`}</p>
      <span className="fgColor-muted">{perLicenseCost} per active committer within the last 90 days</span>
    </div>
  )
}
