import type {PickerRepository} from '@github-ui/repos-picker'

export interface Assessment {
  can_request_another_assessment: boolean
  next_request_available_at: string
  requested_at: string
  last_status_change: string
  is_complete: boolean
  total_scans_wanted: number
  total_scans_completed: number
  total_tokens_found: number
  total_tokens_found_in_public_repo: number
  total_tokens_found_push_protected_patterns: number
  total_tokens_found_non_provider_patterns: number
  total_repositories_with_results: number
  distinct_repos_scanned: number
  tokens: TokenTypeResult[]
}

export interface AssessmentSummary {
  // todo: fix naming inconsistency
  Number: number
  requestedAt: string
}

export interface TokenTypeResult {
  id: string
  name: string
  distinct_repos_count: number
  unique_tokens_found_count: number
}

export interface TokenTypeLocaleResult {
  id: string
  name: string
  distinct_repos_count: string
  unique_tokens_found_count: string
}

export interface Cost {
  increased_license_usage: number
  per_license: string
  total: string
}

export interface Org {
  login: string
  is_ghas_bundled: boolean
  is_ghas_metered: boolean
  active_ghas_trials: string[]
  active_ghas_trials_expiration: Record<string, string>
}

export interface CostEstimationRepository extends PickerRepository {
  tokensFound: number | null
  additionalCommitterIds: number[]
  archived: boolean
}

export interface CsraCostEstimationRepository extends PickerRepository {
  additionalCommitterIds: number[]
  archived: boolean
  vulnerabilitiesFound: number | null
}

export type EnablementRepo = CostEstimationRepository | CsraCostEstimationRepository

export interface EnablementSuccess {
  showBanner: boolean
  repoCount: number
  showSecurityDashboardButton: boolean
}

export interface CodeSecurityEligibleReposResponse {
  eligibleRepos: PickerRepository[]
  totalEligibleRepoCount: number
  suggestedRepoIds: number[]
}

export interface RepositoryResult {
  name: string
  status: string
  total_vulnerability_count: number
  autofix_count: number
}

export interface LanguageResult {
  language: string
  count: number
}

export interface TopRule {
  rule_id: string
  rule_name: string | null
  severity: 'critical' | 'high' | 'medium' | 'low' | null
  distinct_repos: number
  total_vulnerabilities: number
}

export interface CsraAssessment {
  status: 'pending' | 'completed' | 'failed'
  number: number
  created_at: string
  total_vulnerabilities: number
  total_selected_repositories: number
  total_org_repositories: number
  repositories_scanned: RepositoryResult[]
  vulnerabilities_by_language: LanguageResult[]
  top_rules: TopRule[]
  can_request_another_assessment: boolean
  next_request_available_at: string | null
}

export interface AssessmentEligibility {
  eligible: boolean
  has_prior_assessment: boolean
  last_assessment_date: string | null
  cooldown_ends_at: string | null
}

export interface EligibilityResponse {
  sra: AssessmentEligibility
  csra: AssessmentEligibility | null
}

export const DEFAULT_ELIGIBILITY: EligibilityResponse = {
  sra: {eligible: true, has_prior_assessment: false, last_assessment_date: null, cooldown_ends_at: null},
  csra: {eligible: true, has_prior_assessment: false, last_assessment_date: null, cooldown_ends_at: null},
}

export interface CreateAssessmentParams {
  run_sra: boolean
  run_csra: boolean
  repository_ids?: number[]
}

export const ASSESSMENT_SOURCE = {
  SECRET_RISK: 'secret_risk_assessment',
  CODE_SECURITY: 'code_security_risk_assessment',
  SHARED_LANDING: 'shared_landing',
} as const

export type AssessmentSource = (typeof ASSESSMENT_SOURCE)[keyof typeof ASSESSMENT_SOURCE]

export type EnablementDialogContext = 'secret-protection' | 'code-security'
