import {startTransition, useEffect, useMemo, useRef, useState} from 'react'
import {Button, IconButton, Dialog} from '@primer/react'
import {ArrowLeftIcon} from '@primer/octicons-react'
import {useQuery, useQueryClient} from '@github-ui/react-query'
import {debounce} from '@github/mini-throttle'

import type {FilterQuery, SubmitEvent} from '@github-ui/filter-core'

import {type RepoSelection, REPO_SELECTION} from './EnablementDialog/RepositorySelectionGroup'
import {RepositorySelection} from './EnablementDialog/RepositorySelection'
import {CostEstimation} from './EnablementDialog/CostEstimation'
import {queries, useEnableGhspMutation, useEnableGhspOnSelectedReposMutation} from '../api'
import {ALL_REPOS_REPO_COUNT} from '../constants'
import type {Cost, EnablementRepo, EnablementDialogContext, EnablementSuccess, Org} from '../types'
import styles from './EnablementDialog.module.css'
import Pluralize from 'pluralize'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {Review} from './EnablementDialog/Review'

type DialogStep = 'cost-estimation' | 'repository-selection' | 'review'

interface EnablementDialogProps {
  isOpen: boolean
  onClose: () => void
  cost: Cost
  org: Org
  // Handler invoked when enablement succeeds. Accepts the payload to show the banner.
  handleEnablement: (payload: EnablementSuccess) => void
  assessmentNumber: number
  assessmentDate?: string
  isEnterpriseOrMT?: boolean
  context: EnablementDialogContext
}

export function EnablementDialog({
  isOpen,
  onClose,
  cost,
  org,
  handleEnablement,
  assessmentNumber,
  assessmentDate,
  isEnterpriseOrMT = false,
  context,
}: EnablementDialogProps) {
  const productName = context === 'secret-protection' ? 'Secret Protection' : 'Code Security'
  const isSecretProtection = context === 'secret-protection'
  const analyticsCategory = isSecretProtection ? 'sp-enablement-dialog' : 'cs-enablement-dialog'
  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const queryClient = useQueryClient()

  const [repoSelection, setRepoSelection] = useState<RepoSelection>(REPO_SELECTION.ALL)
  const [currentStep, setCurrentStep] = useState<DialogStep>('cost-estimation')
  const [selectedRepoIds, setSelectedRepoIds] = useState<Set<number>>(() => new Set())
  const [filterValue, setFilterValue] = useState('')
  const [debouncedFilterValue, setDebouncedFilterValue] = useState('')
  const [isTransitioning, setIsTransitioning] = useState(false)

  // Debounce the filter value updates to avoid excessive API calls
  const debouncedSetFilter = debounce((value: string) => setDebouncedFilterValue(value.trim()), 300)

  // Query for repositories with server-side filtering.
  // Instead of branching on context here, accept a query factory prop:
  //   fetchReposQuery: (filter: string) => UseQueryOptions<{repositories: CostEstimationRepository[]; totalCount: number}>
  // SRA caller passes: (filter) => queries.fetchRepos(org, assessmentNumber, filter)
  // CSRA caller passes: (filter) => queries.fetchCodeSecurityRepos(org, filter)
  // This removes assessmentNumber from dialog props entirely and keeps the dialog context-agnostic for data fetching.)
  const needsCsraRepos = !isSecretProtection && repoSelection === REPO_SELECTION.SELECTED
  const sraQuery = useQuery({
    ...queries.fetchRepos(org.login, assessmentNumber, debouncedFilterValue),
    enabled: isOpen && isSecretProtection,
  })
  const csraQuery = useQuery({
    ...queries.csraRepos(org.login, debouncedFilterValue),
    enabled: isOpen && needsCsraRepos,
  })
  const activeQuery = isSecretProtection ? sraQuery : csraQuery
  const reposData = activeQuery.data
  const isLoading = activeQuery.isLoading
  const isError = activeQuery.isError

  // Cache query key prefix for merging cached responses across filter variations.
  const cacheQueryKey = useMemo(
    () =>
      isSecretProtection
        ? ['secret-scanning', 'repositories', org.login, assessmentNumber]
        : ['code-security', 'csra-repos', org.login],
    [isSecretProtection, org.login, assessmentNumber],
  )

  // Merge all cached query responses so that repo metadata (especially committer IDs)
  // is preserved for selected repos even when they are hidden by the active filter.
  const allCachedReposById = useMemo(() => {
    const memo = new Map<number, EnablementRepo>()
    const cachedQueries = queryClient.getQueriesData<{repositories: EnablementRepo[]; totalCount: number}>({
      queryKey: cacheQueryKey,
    })
    for (const [, cachedData] of cachedQueries) {
      if (!cachedData) continue
      for (const repo of cachedData.repositories) memo.set(repo.id, repo)
    }
    // Current response takes precedence (fresher data)
    if (reposData) {
      for (const repo of reposData.repositories) memo.set(repo.id, repo)
    }
    return memo
  }, [reposData, queryClient, cacheQueryKey])

  const reposById = useMemo(() => {
    const memo = new Map<number, EnablementRepo>()
    if (!reposData) return memo
    for (const repo of reposData.repositories) memo.set(repo.id, repo)
    return memo
  }, [reposData])
  const totalRepoCount = reposData?.totalCount || 0

  // Ref to track the initial CSRA data load so pre-selection only fires once per dialog open.
  const initialCsraDataRef = useRef<typeof reposData | null>(null)

  // For CSRA, pre-select repos that were in the CSRA assessment results (vulnerabilitiesFound !== null)
  // Uses a ref so this never re-runs when the user applies or clears filters.
  useEffect(() => {
    if (isSecretProtection || !reposData || initialCsraDataRef.current) return
    initialCsraDataRef.current = reposData
    const ids = new Set(
      reposData.repositories
        .filter(repo => 'vulnerabilitiesFound' in repo && repo.vulnerabilitiesFound !== null)
        .map(repo => repo.id),
    )
    if (ids.size > 0) {
      startTransition(() => {
        setSelectedRepoIds(ids)
      })
    }
  }, [isSecretProtection, reposData])

  // Reset the CSRA pre-selection ref when the dialog is closed externally (isOpen flipped
  // to false) without triggering handleCloseDialog. State resets (step, selection, filters)
  // are handled by handleCloseDialog; this effect only covers the ref which handleCloseDialog
  // also resets but needs to be caught for the external-close path.
  useEffect(() => {
    if (!isOpen) {
      initialCsraDataRef.current = null
    }
  }, [isOpen])

  const handleCloseDialog = () => {
    setCurrentStep('cost-estimation')
    setRepoSelection(REPO_SELECTION.ALL)
    setSelectedRepoIds(new Set())
    initialCsraDataRef.current = null
    setFilterValue('')
    setDebouncedFilterValue('')
    setIsTransitioning(false)
    onClose()

    sendClickAnalyticsEvent({
      location: 'security-assessment-post-scan',
      category: analyticsCategory,
      action: 'close',
    })
  }

  // TODO: Accept an enablement callback prop once CSRA wiring is in place (e.g. onEnable: (repoIds: number[] | 'all') => void)
  // instead of using SRA-specific mutations here. Currently the code-security context
  // would incorrectly call the Secret Protection API.
  const enableGhspMutation = useEnableGhspMutation({org: org.login, onSettled: handleCloseDialog})
  const enableGhspOnSelectedReposMutation = useEnableGhspOnSelectedReposMutation({
    org: org.login,
    assessmentNumber,
    onSettled: handleCloseDialog,
  })

  const handleFilterSubmit = (query: FilterQuery, _eventType: SubmitEvent) => {
    const queryValue = query.raw
    setFilterValue(queryValue)
    setDebouncedFilterValue(queryValue.trim()) // Immediate search on submit

    sendClickAnalyticsEvent({
      location: 'security-assessment-post-scan',
      category: analyticsCategory,
      action: 'filter-repos',
    })
  }

  const handleFilterChange = (value: string) => {
    setFilterValue(value)
    debouncedSetFilter(value)
  }

  const selectedCommitterIds = useMemo(() => {
    const memo = new Set<number>()
    for (const repoId of selectedRepoIds) {
      const repo = allCachedReposById.get(repoId)
      const committerIds = repo?.additionalCommitterIds || []
      for (const committerId of committerIds) memo.add(committerId)
    }
    return memo
  }, [allCachedReposById, selectedRepoIds])

  const onChangeSelectedRepos = (selectedRepos: EnablementRepo[]) => {
    setSelectedRepoIds(prev => {
      const next = new Set(prev)
      for (const repoId of reposById.keys()) next.delete(repoId)
      for (const selectedRepo of selectedRepos) next.add(selectedRepo.id)
      return next
    })
  }

  const handleBackClick = () => {
    if (currentStep === 'review') {
      setCurrentStep(repoSelection === REPO_SELECTION.SELECTED ? 'repository-selection' : 'cost-estimation')
    } else if (currentStep === 'repository-selection') {
      setCurrentStep('cost-estimation')
    }
  }

  const handleSelectRepositoriesClick = () => {
    setIsTransitioning(true)
    setCurrentStep('repository-selection')
    startTransition(() => {
      setIsTransitioning(false)
    })
  }

  const handleReviewAndEnableClick = () => {
    setCurrentStep('review')
  }

  const handleEnableClick = () => {
    // Guard: CSRA enablement API is not yet wired. Prevent calling SRA mutations
    // in code-security context regardless of UI state.
    // TODO: Replace with CSRA enablement logic (github/security-products-enablement#2604)
    if (!isSecretProtection) return

    //  If the user chose to enable for all repositories, call the enable-all mutation and
    // set the success banner on success.
    if (repoSelection === REPO_SELECTION.ALL) {
      enableGhspMutation.mutate(
        {includePrivateRepos: true},
        {
          onSuccess: data => {
            handleEnablement({
              showBanner: true,
              repoCount: ALL_REPOS_REPO_COUNT,
              showSecurityDashboardButton: data.show_security_dashboard_button,
            })
          },
        },
      )
      sendClickAnalyticsEvent({
        location: 'security-assessment-post-scan',
        category: analyticsCategory,
        action: 'enable-all-repos',
      })
      return
    }

    // Otherwise enable for the selected repositories. Guard against no selection.
    if (selectedRepoIds.size === 0) {
      return
    }

    const repoIds = Array.from(selectedRepoIds)
    enableGhspOnSelectedReposMutation.mutate(
      {repoIds},
      {
        onSuccess: data => {
          const repoCount = typeof data.repo_count === 'number' ? data.repo_count : repoIds.length
          handleEnablement({
            showBanner: true,
            repoCount,
            showSecurityDashboardButton: data.show_security_dashboard_button,
          })
        },
      },
    )

    sendClickAnalyticsEvent({
      location: 'security-assessment-post-scan',
      category: analyticsCategory,
      action: 'enable-selected-repos',
      enabledRepoCount: `${selectedRepoIds.size}`,
    })
  }

  const isMutating = enableGhspMutation.isPending || enableGhspOnSelectedReposMutation.isPending

  const calculateCost = () => {
    const perLicenseAmount = parseFloat(cost.per_license.replace(/[$,]/g, '')) // Turns cost.per_license from something like "$9,999.99" to 9999.99
    const calculatedTotalCost = selectedCommitterIds.size * perLicenseAmount

    return {
      totalCost: calculatedTotalCost.toLocaleString('en-US', {style: 'currency', currency: 'USD'}),
      licenseCount: selectedCommitterIds.size,
    }
  }

  const renderFooter = () => {
    if (currentStep === 'repository-selection') {
      const {totalCost, licenseCount} = calculateCost()

      return (
        <div
          className={`d-flex ${isSecretProtection ? 'flex-justify-between' : 'flex-justify-end'} flex-items-center tmp-p-3 border-top`}
        >
          {isSecretProtection && (
            <div>
              <div data-testid="total-cost" className="text-semibold">
                Total cost: {totalCost} / month
              </div>
              <div data-testid="license-count" className="color-fg-muted text-small">
                {licenseCount} {productName} {Pluralize('license', licenseCount, false)} required
              </div>
            </div>
          )}
          <div className="d-flex flex-justify-end gap-2">
            <Button onClick={handleCloseDialog}>Cancel</Button>
            <Button
              variant="primary"
              onClick={handleReviewAndEnableClick}
              loading={isMutating}
              disabled={repoSelection === REPO_SELECTION.SELECTED && selectedRepoIds.size === 0}
              count={selectedRepoIds.size || undefined}
            >
              Review and enable
            </Button>
          </div>
        </div>
      )
    }

    if (currentStep === 'review') {
      // TODO: Enable once CSRA enablement endpoint is implemented (github/security-products-enablement#2604)
      return (
        <div className="d-flex flex-justify-end gap-2 tmp-p-3 border-top">
          <Button onClick={handleCloseDialog}>Cancel</Button>
          <Button variant="primary" onClick={handleEnableClick} loading={isMutating}>
            Enable {productName}
          </Button>
        </div>
      )
    }

    return (
      <div className="d-flex flex-justify-end gap-2 tmp-p-3 border-top">
        <Button onClick={handleCloseDialog}>Cancel</Button>
        {repoSelection === REPO_SELECTION.SELECTED ? (
          <Button variant="primary" onClick={handleSelectRepositoriesClick}>
            Select repositories
          </Button>
        ) : (
          <Button variant="primary" onClick={handleReviewAndEnableClick} loading={isMutating}>
            Review and enable
          </Button>
        )}
      </div>
    )
  }

  const getDialogTitle = () => {
    switch (currentStep) {
      case 'repository-selection':
        return (
          <div className="d-flex flex-items-center">
            <IconButton
              aria-label="Back to cost estimation"
              icon={ArrowLeftIcon}
              variant="invisible"
              size="small"
              onClick={handleBackClick}
              className="mr-1"
            />
            Select repositories
          </div>
        )
      case 'review':
        return (
          <div className="d-flex flex-items-center">
            <IconButton
              aria-label="Back to previous step"
              icon={ArrowLeftIcon}
              variant="invisible"
              size="small"
              onClick={handleBackClick}
              className="mr-1"
            />
            Enable {productName}
          </div>
        )
      case 'cost-estimation':
      default:
        return isSecretProtection ? `Estimate cost of ${productName}` : `Enable ${productName}`
    }
  }

  const renderDialogContent = () => {
    switch (currentStep) {
      case 'repository-selection':
        return (
          <RepositorySelection
            selectedRepoIds={selectedRepoIds}
            onRepositorySelectionChange={onChangeSelectedRepos}
            selectedCommitterIds={selectedCommitterIds}
            reposById={reposById}
            totalRepoCount={totalRepoCount}
            isLoading={isLoading || isTransitioning}
            isError={isError}
            filterValue={filterValue}
            onFilterChange={handleFilterChange}
            onFilterSubmit={handleFilterSubmit}
            orgLogin={org.login}
          />
        )
      case 'review':
        return (
          <Review
            additionalCost={repoSelection === REPO_SELECTION.ALL ? cost.total : calculateCost().totalCost}
            org={org.login}
            cost={cost}
            repoSelection={repoSelection}
            selectedReposCount={selectedRepoIds.size}
            selectedLicenseCount={
              repoSelection === REPO_SELECTION.ALL ? cost.increased_license_usage : calculateCost().licenseCount
            }
            context={context}
            productName={productName}
          />
        )
      case 'cost-estimation':
      default:
        return (
          <CostEstimation
            additionalCost={repoSelection === REPO_SELECTION.ALL ? cost.total : calculateCost().totalCost}
            repoSelection={repoSelection}
            selectedReposCount={selectedRepoIds.size}
            selectedLicenseCount={
              repoSelection === REPO_SELECTION.ALL ? cost.increased_license_usage : calculateCost().licenseCount
            }
            onRepoSelectionChange={setRepoSelection}
            cost={cost}
            isEnterpriseOrMT={isEnterpriseOrMT}
            org={org}
            context={context}
            productName={productName}
          />
        )
    }
  }

  return (
    isOpen && (
      <Dialog
        onClose={handleCloseDialog}
        height={currentStep === 'repository-selection' ? 'large' : 'auto'}
        title={getDialogTitle()}
        subtitle={
          currentStep === 'repository-selection' && (
            <div className="tmp-ml-5">
              {isSecretProtection ? (
                <>
                  Showing repositories without Secret Protection. Committers refers to distinct contributors with
                  activity in the past 90 days. Secret count based on <span>{assessmentDate || 'latest'}</span>{' '}
                  assessment.
                </>
              ) : (
                <>
                  Showing all repositories without Code Security enabled. Committers refers to distinct contributors
                  with activity in the past 90 days. Vulnerability count based on latest assessment.
                </>
              )}
            </div>
          )
        }
        renderFooter={renderFooter}
        className={currentStep === 'repository-selection' ? styles.enablementDialog : undefined}
      >
        {renderDialogContent()}
      </Dialog>
    )
  )
}
