import {Link} from '@primer/react'
import {REPO_SELECTION, type RepoSelection} from './RepositorySelectionGroup'
import type {Cost, EnablementDialogContext} from '../../types'
import {CostSummaryBox} from './CostSummaryBox'
import {getCostDisplayValues} from './enablement-dialog-utils'

interface ReviewProps {
  additionalCost: string
  org: string
  cost: Cost
  repoSelection: RepoSelection
  selectedReposCount: number
  selectedLicenseCount: number
  context: EnablementDialogContext
  productName: string
}

export function Review({
  additionalCost,
  org,
  cost,
  repoSelection,
  selectedReposCount,
  selectedLicenseCount,
  context,
  productName,
}: ReviewProps) {
  const isSecretProtection = context === 'secret-protection'

  const {licenseCount, repositoryCountText, perLicenseCost} = getCostDisplayValues(
    repoSelection,
    cost,
    selectedLicenseCount,
    selectedReposCount,
  )
  const reposToEnableText =
    repoSelection === REPO_SELECTION.SELECTED ? 'selected repositories' : 'all at risk repositories'

  const confirmationText = isSecretProtection
    ? `Would you like to enable ${productName} with secret scanning alerts and push protection for`
    : `Would you like to enable ${productName} with code scanning and Copilot Autofix for`

  return (
    <>
      <p>
        {confirmationText} {reposToEnableText}?
      </p>
      {isSecretProtection && (
        <CostSummaryBox
          additionalCost={additionalCost}
          licenseCount={licenseCount}
          repositoryCountText={repositoryCountText}
          perLicenseCost={perLicenseCost}
          variant="review"
          productName={productName}
        />
      )}
      {/* Billing notice applies to both SRA and CSRA contexts: both products charge per active committer. */}
      <span className="fgColor-muted f-small lh-default">
        You will be charged for additional committers in your next billing cycle.{' '}
        <Link href={`/organizations/${org}/settings/billing`} inline>
          Review billing information
        </Link>{' '}
        for more details.
      </span>
    </>
  )
}
