import {queryOptions, useMutation, useQueryClient} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useNavigate} from '@github-ui/use-navigate'

import {
  riskAssessmentJsonPath,
  riskAssessmentPath,
  fetchReposPath,
  enableGhspPath,
  enableGhspOnSelectedReposPath,
  riskAssessmentScanRepositoriesPath,
  csraJsonPath,
  csraReposPath,
  riskAssessmentEligibilityPath,
} from '../paths'
import type {
  Assessment,
  CostEstimationRepository,
  CsraCostEstimationRepository,
  CodeSecurityEligibleReposResponse,
  CsraAssessment,
  EligibilityResponse,
  CreateAssessmentParams,
  AssessmentSource,
} from '../types'
import {ASSESSMENT_SOURCE} from '../types'

export function initialAssessment(): Assessment {
  const now = new Date()
  const nextAvailableAt = new Date()
  nextAvailableAt.setDate(nextAvailableAt.getDate() + 90)
  return {
    can_request_another_assessment: false,
    next_request_available_at: nextAvailableAt.toISOString(),
    requested_at: now.toISOString(),
    last_status_change: now.toISOString(),
    is_complete: false,
    total_scans_wanted: 1,
    total_scans_completed: 0,
    total_tokens_found: 0,
    total_tokens_found_in_public_repo: 0,
    total_tokens_found_push_protected_patterns: 0,
    total_tokens_found_non_provider_patterns: 0,
    total_repositories_with_results: 0,
    distinct_repos_scanned: 0,
    tokens: [],
  }
}

export const queries = {
  assessment: (org: string, number: number | null = null) =>
    queryOptions({
      queryKey: ['secret-scanning', 'assessment', org, number] as const,
      // Return type is nullable to allow `initialData` to be set to null
      queryFn: async ({queryKey: [, , orgLogin]}): Promise<Assessment | null> => {
        const res = await reactFetchJSON(riskAssessmentJsonPath(orgLogin))
        if (!res.ok) {
          throw new Error('Failed to fetch assessment')
        }
        const newAssessment = (await res.json()) as Assessment | null
        if (!newAssessment) {
          throw new Error('Assessment not found')
        }
        return newAssessment
      },
    }),
  fetchRepos: (org: string, assessment: number, query?: string) =>
    queryOptions({
      queryKey: ['secret-scanning', 'repositories', org, assessment, query] as const,
      queryFn: async ({
        queryKey: [, , orgLogin, assessmentNumber, searchQuery],
      }): Promise<{repositories: CostEstimationRepository[]; totalCount: number}> => {
        const url = new URL(fetchReposPath(orgLogin, assessmentNumber), window.location.origin)
        url.searchParams.set('q', searchQuery || '')

        const res = await reactFetchJSON(url.toString())

        if (!res.ok) {
          throw new Error(`Failed to fetch repositories: ${res.status}`)
        }

        const data = (await res.json()) as {items: CostEstimationRepository[]; totalCount: number}
        return {repositories: data.items, totalCount: data.totalCount}
      },
    }),
  csraRepos: (org: string, query?: string) => {
    const normalizedQuery = query?.trim() || undefined
    return queryOptions({
      queryKey: ['code-security', 'csra-repos', org, normalizedQuery] as const,
      queryFn: async ({
        queryKey: [, , orgLogin, searchQuery],
      }): Promise<{repositories: CsraCostEstimationRepository[]; totalCount: number}> => {
        const url = new URL(csraReposPath(orgLogin), window.location.origin)
        url.searchParams.set('q', searchQuery || '')

        const res = await reactFetchJSON(url.toString())

        if (!res.ok) {
          throw new Error(`Failed to fetch CSRA repositories: ${res.status}`)
        }

        const data = (await res.json()) as {items: CsraCostEstimationRepository[]; totalCount: number}
        return {repositories: data.items, totalCount: data.totalCount}
      },
    })
  },
  codeSecurityEligibleRepos: (org: string, query?: string) =>
    queryOptions({
      queryKey: ['code-security', 'eligible-repos', org, query] as const,
      queryFn: async ({queryKey: [, , orgLogin, searchQuery]}): Promise<CodeSecurityEligibleReposResponse> => {
        const res = await reactFetchJSON(riskAssessmentScanRepositoriesPath(orgLogin, searchQuery))

        if (!res.ok) {
          throw new Error(`Failed to fetch code security eligible repositories: ${res.status}`)
        }

        return (await res.json()) as CodeSecurityEligibleReposResponse
      },
    }),
  csraAssessment: (org: string) =>
    queryOptions({
      queryKey: ['code-security', 'csra-assessment', org] as const,
      queryFn: async ({queryKey: [, , orgLogin]}): Promise<CsraAssessment | null> => {
        const res = await reactFetchJSON(csraJsonPath(orgLogin))
        if (res.status === 404) return null
        if (!res.ok) throw new Error(`Failed to fetch CSRA assessment: ${res.status}`)
        return (await res.json()) as CsraAssessment
      },
    }),
  eligibility: (org: string) =>
    queryOptions({
      queryKey: ['risk-assessment', 'eligibility', org] as const,
      queryFn: async ({queryKey: [, , orgLogin]}): Promise<EligibilityResponse> => {
        const res = await reactFetchJSON(riskAssessmentEligibilityPath(orgLogin))

        if (!res.ok) {
          throw new Error(`Failed to fetch assessment eligibility: ${res.status}`)
        }

        return (await res.json()) as EligibilityResponse
      },
    }),
}

export function useCreateAssessmentMutation({org, source}: {org: string; source?: AssessmentSource}) {
  const client = useQueryClient()
  const navigate = useNavigate()
  return useMutation({
    mutationFn: async (params?: CreateAssessmentParams | void) => {
      const res = await reactFetchJSON(riskAssessmentPath(org), {
        method: 'POST',
        body: params,
      })
      if (!res.ok) {
        throw new Error(`Failed to start assessment, status: ${res.status}`)
      }
    },
    onSuccess: (_data, variables) => {
      const runSra = !variables || variables.run_sra
      const runCsra = variables?.run_csra ?? false

      // Update frontend caches so the UI shows in-progress state
      // for the assessments that were actually submitted.
      if (runSra) {
        client.setQueryData(queries.assessment(org, null).queryKey, initialAssessment())
      }
      if (runCsra) {
        void client.invalidateQueries({queryKey: queries.csraAssessment(org).queryKey})
      }

      // Legacy flow (FF disabled): no params means SRA-only, always navigate to SRA page.
      if (!variables) {
        navigate(riskAssessmentPath(org))
        return
      }

      // Navigate to the appropriate tab:
      // SRA-only or both-from-SRA-tab → SRA tab
      // CSRA-only or both-from-CSRA/shared → CSRA tab
      if (runSra && (!runCsra || source === ASSESSMENT_SOURCE.SECRET_RISK)) {
        navigate(`${riskAssessmentPath(org)}?assessmentType=secret-protection`)
      } else {
        navigate(`${riskAssessmentPath(org)}?assessmentType=code-security`)
      }
    },
  })
}

type EnableGhspResponse = {show_security_dashboard_button: boolean}

export function useEnableGhspMutation({org, onSettled}: {org: string; onSettled?: () => void}) {
  return useMutation<EnableGhspResponse, unknown, {includePrivateRepos: boolean}>({
    mutationFn: async ({includePrivateRepos}: {includePrivateRepos: boolean}): Promise<EnableGhspResponse> => {
      const res = await reactFetchJSON(enableGhspPath(org), {
        method: 'PATCH',
        body: {includePrivateRepos},
      })

      if (!res.ok) {
        throw new Error('Failed to enable secret protection')
      }

      const data = (await res.json()) as EnableGhspResponse
      return data
    },
    onSettled: () => {
      if (onSettled) onSettled()
    },
  })
}

type EnableGhspOnSelectedReposResponse = {repo_count: number; show_security_dashboard_button: boolean}

export function useEnableGhspOnSelectedReposMutation({
  org,
  assessmentNumber,
  onSettled,
}: {
  org: string
  assessmentNumber: number
  onSettled?: () => void
}) {
  const client = useQueryClient()

  return useMutation<EnableGhspOnSelectedReposResponse, unknown, {repoIds: number[]}>({
    mutationFn: async ({repoIds}: {repoIds: number[]}): Promise<EnableGhspOnSelectedReposResponse> => {
      const res = await reactFetchJSON(enableGhspOnSelectedReposPath(org), {
        method: 'PATCH',
        body: {repoIds},
      })

      if (!res.ok) {
        throw new Error('Failed to enable secret protection on selected repositories')
      }

      const data = (await res.json()) as EnableGhspOnSelectedReposResponse
      return data
    },
    onSettled: () => {
      // Invalidate repository query so UI updates
      void client.invalidateQueries({queryKey: queries.fetchRepos(org, assessmentNumber).queryKey})
      if (onSettled) onSettled()
    },
  })
}
