import {useState} from 'react'
import {Button, TextInput, FormControl, Link} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {ChevronDownIcon, ChevronUpIcon} from '@primer/octicons-react'
import {useClickAnalytics} from '@github-ui/use-analytics'
import Pluralize from 'pluralize'

// Default values for ROI calculation
const DEFAULT_DEVELOPER_SALARY = 150000
const DEFAULT_SECRETS_FOUND = 70
const DEFAULT_HOURS_TO_REMEDIATE = 3
const WORKING_HOURS_PER_YEAR = 2080

interface ROICalculatorProps {
  isOpen: boolean
  onClose: () => void
  totalPreventableSecretsFound?: number
  showEnablementDialog?: boolean
  onEnableAllRepos?: () => void
  onOpenEnablementDialog?: () => void
}

export function ROICalculator({
  isOpen,
  onClose,
  totalPreventableSecretsFound,
  showEnablementDialog = true,
  onEnableAllRepos,
  onOpenEnablementDialog,
}: ROICalculatorProps) {
  const [averageDeveloperSalary, setAverageDeveloperSalary] = useState(DEFAULT_DEVELOPER_SALARY.toString())
  const [timeToRemediate, setTimeToRemediate] = useState(DEFAULT_HOURS_TO_REMEDIATE.toString())
  const [showAbout, setShowAbout] = useState(false)
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const calculateROI = () => {
    const salary = parseFloat(averageDeveloperSalary) || DEFAULT_DEVELOPER_SALARY
    const secretsFound = totalPreventableSecretsFound || DEFAULT_SECRETS_FOUND
    const hoursPerSecret = parseFloat(timeToRemediate) || DEFAULT_HOURS_TO_REMEDIATE

    // Calculate hourly rate (annual salary ÷ working hours per year)
    const hourlyRate = salary / WORKING_HOURS_PER_YEAR

    // Calculate per-secret cost
    const costPerSecret = hourlyRate * hoursPerSecret

    const timeSaved = secretsFound * hoursPerSecret
    const moneySaved = Math.round(timeSaved * hourlyRate)

    return {
      secretsPrevented: secretsFound,
      timeSaved,
      moneySaved,
      costPerSecret: Math.round(costPerSecret),
    }
  }

  const roiData = calculateROI()

  const renderFooter = () => (
    <div className="d-flex flex-justify-end gap-2 tmp-p-3 border-top">
      <Button onClick={onClose}>Cancel</Button>
      <Button
        variant="primary"
        onClick={() => {
          let opener = onEnableAllRepos
          if (showEnablementDialog) {
            opener = onOpenEnablementDialog ?? onEnableAllRepos
          }
          opener?.()
          onClose()
        }}
      >
        {showEnablementDialog ? 'Enable Secret Protection' : 'Enable for all repositories'}
      </Button>
    </div>
  )

  return (
    <>
      {isOpen && (
        <Dialog onClose={onClose} title="Push protection savings" renderFooter={renderFooter} width="xlarge">
          <div className="tmp-mb-3 text-left">
            <div className="h5 text-bold mb-1">
              <span>{totalPreventableSecretsFound?.toLocaleString() || DEFAULT_SECRETS_FOUND.toString()}</span>
              <span>
                {' '}
                preventable {Pluralize('leak', totalPreventableSecretsFound || DEFAULT_SECRETS_FOUND, false)}
              </span>
            </div>
            <div className="fgColor-muted f6">
              {totalPreventableSecretsFound
                ? 'Secrets preventable with push protection, based on your risk assessment'
                : 'Using default value'}
            </div>
          </div>

          <div className="d-flex gap-3 tmp-mb-3">
            <FormControl className="flex-1">
              <FormControl.Label>Average developer salary</FormControl.Label>
              <TextInput
                block
                type="number"
                trailingVisual="USD"
                value={averageDeveloperSalary}
                onChange={e => setAverageDeveloperSalary(e.target.value)}
              />
            </FormControl>
            <FormControl className="flex-1">
              <FormControl.Label>Time to remediate</FormControl.Label>
              <TextInput
                block
                type="number"
                trailingVisual="hours"
                value={timeToRemediate}
                onChange={e => setTimeToRemediate(e.target.value)}
              />
            </FormControl>
          </div>

          <div className="tmp-mb-3">
            <div className="h5 mb-0">Return on investment</div>
          </div>
          <div className="tmp-p-3 bgColor-inset rounded-2">
            <div className="d-flex flex-column gap-2">
              <div className="d-flex flex-justify-between">
                <div className="d-flex flex-column">
                  <span>Secrets prevented</span>
                  <span className="color-fg-muted f6">GitHub blocks secrets with push protection</span>
                </div>
                <span>
                  {roiData.secretsPrevented.toLocaleString()} {Pluralize('secret', roiData.secretsPrevented, false)}
                </span>
              </div>
              <div className="d-flex flex-justify-between">
                <div className="d-flex flex-column">
                  <span>Time saved</span>
                  <span className="color-fg-muted f6">Based on time to remediate</span>
                </div>
                <span>
                  {roiData.timeSaved.toLocaleString()} {Pluralize('hour', roiData.timeSaved, false)}
                </span>
              </div>
              <div className="d-flex flex-justify-between">
                <div className="d-flex flex-column">
                  <span>Potential savings with push protection</span>
                  <span className="color-fg-muted f6">
                    <span>Based on developer salary and time to remediate: $</span>
                    <span>{roiData.costPerSecret.toLocaleString()}</span>
                    <span> per secret</span>
                  </span>
                </div>
                <span>${roiData.moneySaved.toLocaleString()} savings</span>
              </div>
            </div>
          </div>
          <div className="tmp-mt-3">
            <span className="color-fg-muted f6">
              <strong>Did you know?</strong> This calculator does not include the cost of a data breach, which averaged
              $4.88M in 2024 according to IBM.
            </span>{' '}
            <Link
              href="https://github.com/resources/whitepapers/secret-scanning-a-key-to-your-cybersecurity-strategy"
              inline
              className="f6 color-fg-muted"
              onClick={() =>
                sendClickAnalyticsEvent({
                  location: 'roi-calculator',
                  category: 'roi-calculator',
                  action: 'learn-more-whitepaper',
                  tag: 'link',
                })
              }
            >
              Learn more in our expert guide
            </Link>
          </div>
          <div className="tmp-mt-3">
            <Link as="button" onClick={() => setShowAbout(!showAbout)} className="d-flex flex-items-center gap-1">
              <strong>About this calculator</strong>
              {showAbout ? <ChevronUpIcon size={16} /> : <ChevronDownIcon size={16} />}
            </Link>
            {showAbout && (
              <ul className="color-fg-muted f6 mt-2 tmp-pl-3">
                <li>
                  Estimated savings are based only on push protection.{' '}
                  <strong>
                    Calculations do not include additional time savings from other Secret Protection features like
                    faster triage and remediation of existing secrets.
                  </strong>
                </li>
                <li>
                  Calculations are based on your risk assessment findings and are estimates only. Results may vary and
                  are not guaranteed by GitHub. Not intended as financial advice
                </li>
                <li>If no preventable secrets were detected, the estimates assume 70 preventable secrets.</li>
              </ul>
            )}
          </div>
        </Dialog>
      )}
    </>
  )
}
