import {useState, useMemo, useCallback} from 'react'
import {Button, Dialog, IconButton} from '@primer/react'
import {ArrowLeftIcon} from '@primer/octicons-react'
import {useQuery} from '@github-ui/react-query'
import {useClickAnalytics} from '@github-ui/use-analytics'

import {queries} from '../api'
import {MAX_CODE_SECURITY_REPOS} from '../constants'
import type {CreateAssessmentParams, EligibilityResponse} from '../types'
import {AssessmentSelection} from './RunAssessmentDialog/AssessmentSelection'
import {RepositorySelection} from './RunAssessmentDialog/RepositorySelection'
import styles from './RunAssessmentDialog.module.css'

type DialogStep = 'select-assessment' | 'select-repos'

interface RunAssessmentDialogProps {
  onClose: () => void
  onStartScan: (params: CreateAssessmentParams) => void
  org: {login: string}
  source: string
  eligibility: EligibilityResponse
}

export function RunAssessmentDialog({onClose, onStartScan, org, source, eligibility}: RunAssessmentDialogProps) {
  const {login: orgLogin} = org
  const [currentStep, setCurrentStep] = useState<DialogStep>('select-assessment')
  const [shouldRunSra, setShouldRunSra] = useState(eligibility.sra.eligible)
  const [shouldRunCsra, setShouldRunCsra] = useState(eligibility.csra?.eligible ?? false)
  const [showAssessmentWarning, setShowAssessmentWarning] = useState(false)
  const [showRepoSelectionWarning, setShowRepoSelectionWarning] = useState(false)
  const [userSelectedRepoIds, setUserSelectedRepoIds] = useState<Set<number> | null>(null)
  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const {
    data: unfilteredData,
    isLoading: isReposLoading,
    isError: isReposError,
  } = useQuery(queries.codeSecurityEligibleRepos(orgLogin, undefined))

  const selectedRepoIds = useMemo(() => {
    if (userSelectedRepoIds !== null) return userSelectedRepoIds
    return new Set(unfilteredData?.suggestedRepoIds ?? [])
  }, [userSelectedRepoIds, unfilteredData?.suggestedRepoIds])

  // Reset state and close dialog without sending analytics
  const resetAndClose = useCallback(() => {
    setCurrentStep('select-assessment')
    setShouldRunSra(eligibility.sra.eligible)
    setShouldRunCsra(eligibility.csra?.eligible ?? false)
    setShowAssessmentWarning(false)
    setShowRepoSelectionWarning(false)
    setUserSelectedRepoIds(null)
    onClose()
  }, [onClose, eligibility])

  const handleCancel = useCallback(() => {
    sendClickAnalyticsEvent({
      category: 'RISK_ASSESSMENT',
      action: 'cancel',
      label: `source:${source};org:${orgLogin}`,
    })
    resetAndClose()
  }, [resetAndClose, sendClickAnalyticsEvent, source, orgLogin])

  const handleRunSraChange = useCallback((checked: boolean) => {
    setShouldRunSra(checked)
    setShowAssessmentWarning(false)
  }, [])

  const handleRunCsraChange = useCallback((checked: boolean) => {
    setShouldRunCsra(checked)
    setShowAssessmentWarning(false)
  }, [])

  const handleContinue = useCallback(() => {
    if (!shouldRunSra && !shouldRunCsra) {
      setShowAssessmentWarning(true)
      return
    }

    if (shouldRunCsra) {
      setCurrentStep('select-repos')
    } else {
      sendClickAnalyticsEvent({
        category: 'RISK_ASSESSMENT',
        action: 'start_scan',
        label: `source:${source};org:${orgLogin}`,
      })
      onStartScan({run_sra: true, run_csra: false})
      resetAndClose()
    }
  }, [shouldRunSra, shouldRunCsra, onStartScan, resetAndClose, sendClickAnalyticsEvent, source, orgLogin])

  const handleSelectionChange = useCallback((newSelectedIds: Set<number>) => {
    setUserSelectedRepoIds(newSelectedIds)
    if (newSelectedIds.size > 0) {
      setShowRepoSelectionWarning(false)
    }
  }, [])

  const handleBack = useCallback(() => {
    setShowRepoSelectionWarning(false)
    setCurrentStep('select-assessment')
  }, [])

  const handleStartScan = useCallback(() => {
    if (isReposLoading || isReposError) return

    if (selectedRepoIds.size === 0) {
      setShowRepoSelectionWarning(true)
      return
    }
    if (selectedRepoIds.size > MAX_CODE_SECURITY_REPOS) {
      return
    }
    sendClickAnalyticsEvent({
      category: 'RISK_ASSESSMENT',
      action: 'start_scan',
      label: `source:${source};org:${orgLogin}`,
    })
    onStartScan({
      run_sra: shouldRunSra,
      run_csra: shouldRunCsra,
      repository_ids: Array.from(selectedRepoIds),
    })
    resetAndClose()
  }, [
    onStartScan,
    shouldRunSra,
    shouldRunCsra,
    selectedRepoIds,
    resetAndClose,
    isReposLoading,
    isReposError,
    sendClickAnalyticsEvent,
    source,
    orgLogin,
  ])

  const getDialogTitle = () => {
    switch (currentStep) {
      case 'select-repos':
        return (
          <div className="d-flex flex-items-center">
            <IconButton
              aria-label="Back to assessment selection"
              icon={ArrowLeftIcon}
              variant="invisible"
              size="small"
              onClick={handleBack}
              className="mr-1"
            />
            Select repositories for Code Security scan
          </div>
        )
      case 'select-assessment':
      default:
        return 'Scan organization'
    }
  }

  const renderContent = () => {
    switch (currentStep) {
      case 'select-assessment':
        return (
          <AssessmentSelection
            eligibility={eligibility}
            runSra={shouldRunSra}
            runCsra={shouldRunCsra}
            onRunSraChange={handleRunSraChange}
            onRunCsraChange={handleRunCsraChange}
            showWarning={showAssessmentWarning}
          />
        )
      case 'select-repos':
        return (
          <RepositorySelection
            selectedRepoIds={selectedRepoIds}
            onSelectionChange={handleSelectionChange}
            orgLogin={orgLogin}
            showSelectionWarning={showRepoSelectionWarning}
          />
        )
    }
  }

  const renderFooter = () => {
    switch (currentStep) {
      case 'select-assessment':
        return (
          <div className="d-flex flex-justify-end gap-2 pr-p-3 border-top">
            <Button onClick={handleCancel}>Cancel</Button>
            <Button variant="primary" onClick={handleContinue}>
              Continue
            </Button>
          </div>
        )
      case 'select-repos':
        return (
          <div className="d-flex flex-justify-end gap-2 pr-p-3 border-top">
            <Button onClick={handleCancel}>Cancel</Button>
            <Button variant="primary" onClick={handleStartScan}>
              Start scan
            </Button>
          </div>
        )
    }
  }

  return (
    <Dialog
      title={getDialogTitle()}
      onClose={handleCancel}
      renderFooter={renderFooter}
      height={currentStep === 'select-repos' ? 'large' : 'auto'}
      width={'large'}
      className={styles.runAssessmentDialog}
    >
      {renderContent()}
    </Dialog>
  )
}
