import {useState} from 'react'
import {clsx} from 'clsx'
import {useQuery} from '@github-ui/react-query'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {Banner, Heading, Link} from '@primer/react'
import {Accordion} from '@github-ui/accordion'

import {AssessmentResultPage} from '../components/AssessmentResultPage'
import {RiskAssessmentBanner} from '../components/RiskAssessmentBanner'
import {RiskAssessmentFaq} from '../components/RiskAssessmentFaq'
import {RunAssessmentDialog} from '../components/RunAssessmentDialog'
import type {Assessment, AssessmentSummary, Cost, CreateAssessmentParams, Org} from '../types'
import {DEFAULT_ELIGIBILITY, ASSESSMENT_SOURCE} from '../types'
import {queries, useCreateAssessmentMutation} from '../api'
import styles from './SecretRiskAssessmentPage.module.css'

const SOURCE = ASSESSMENT_SOURCE.SECRET_RISK

export interface SecretRiskAssessmentPagePayload {
  help_url: string
  org: Org
  number?: number
  assessment?: Assessment | null
  assessmentList?: AssessmentSummary[] | null
  cost: Cost
  can_skip_rescan: boolean
  hawaii_exp_variant: number
  is_enterprise_or_mt: boolean
  show_enable_secret_protection_button: boolean
  show_error_banner?: boolean
  show_enable_secret_protection_banner?: boolean
}

export function SecretRiskAssessmentPage({refetchInterval = 5000}: {refetchInterval?: number}) {
  // Guarantee `assessment` defaults to null (not undefined)
  // so `initialData` isn't considered unset and causes a query.
  const {
    help_url,
    org,
    number = null,
    assessment = null,
    assessmentList = null,
    cost,
    can_skip_rescan,
    hawaii_exp_variant,
    is_enterprise_or_mt,
    show_enable_secret_protection_button,
    show_error_banner = false,
    show_enable_secret_protection_banner = true,
  } = useRoutePayload<SecretRiskAssessmentPagePayload>()
  const {data, isError} = useQuery({
    ...queries.assessment(org.login, number),
    initialData: assessment,
    // Assessment is only gonna change if it's incomplete.
    staleTime: Infinity,
    refetchInterval: query => {
      // Don't poll for previous assessments cuz they're completed
      if (number !== null) return false
      // Stop polling if query fails 3 times.
      if (query.state.errorUpdateCount >= 3) {
        return false
      }
      const newAssessment = query.state.data
      if (!newAssessment || newAssessment?.is_complete) {
        return false
      }
      return refetchInterval
    },
  })

  if (!data || show_error_banner) {
    return <LandingPage org={org} showErrorBanner={show_error_banner} />
  }

  return (
    <>
      {isError && !data.is_complete && (
        <Banner
          className="tmp-mb-3"
          variant="critical"
          title="Error"
          description="Failed to update assessment progress. Please refresh the page, or try again later."
        />
      )}
      <AssessmentResultPage
        assessment={data}
        assessmentList={assessmentList}
        cost={cost}
        helpUrl={help_url}
        org={org}
        canSkipRescan={can_skip_rescan}
        hawaiiExpVariant={hawaii_exp_variant}
        isEnterpriseOrMT={is_enterprise_or_mt}
        showEnableSecretProtectionButton={show_enable_secret_protection_button}
        currentAssessmentNumber={number ?? undefined}
        showEnableSecretProtectionBanner={show_enable_secret_protection_banner}
      />
    </>
  )
}

function LandingPage({org, showErrorBanner = false}: {org: Org; showErrorBanner?: boolean}) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isCodeSecurityRiskAssessmentEnabled = useFeatureFlag('code_security_risk_assessment')
  const {data: eligibility, isLoading: isEligibilityLoading} = useQuery(queries.eligibility(org.login))
  const resolvedEligibility = eligibility ?? DEFAULT_ELIGIBILITY
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showCopilotAssist = useFeatureFlag('risk_assessment_copilot_assistive')

  const mutation = useCreateAssessmentMutation({
    org: org.login,
    source: SOURCE,
  })

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const sendLegacyScanAnalytics = () => {
    sendClickAnalyticsEvent({
      location: 'security-assessment-pre-scan',
      category: 'find-secrets-banner',
      action: 'scan-organization',
      tag: 'button',
      group: 'expand',
    })
  }

  const handleScanClick = () => {
    if (isCodeSecurityRiskAssessmentEnabled) {
      // Open dialog which handles its own analytics
      setIsDialogOpen(true)
    } else {
      // Legacy flow: Send existing click analytics for backward compatibility
      sendLegacyScanAnalytics()
      mutation.mutate()
    }
  }

  const handleStartScan = (params: CreateAssessmentParams) => {
    // Send legacy click analytics for backward compatibility
    sendLegacyScanAnalytics()
    mutation.mutate(params)
  }

  return (
    <>
      {showErrorBanner && (
        <Banner
          className="tmp-mb-3"
          variant="critical"
          title="Error"
          description="Failed to load assessment data. Please refresh the page, or try again later."
        />
      )}
      {mutation.isError && (
        <Banner
          variant="critical"
          title="Error"
          description="Failed to scan your organization. Please try again later."
          className="tmp-mb-3"
        />
      )}

      <RiskAssessmentBanner
        className="find-exposed-secrets"
        title="Find secrets exposed in your organization"
        description="Scan your organization now for free and receive a secret leaks audit with aggregate insights on any public leaks, leak sources, and token types."
        descriptionMaxWidth={400}
        primaryAction={{
          onClick: handleScanClick,
          label: 'Scan your organization',
        }}
        secondaryAction={{
          href: 'https://gh.io/choosing-ghsp',
          onClick: () => {
            sendClickAnalyticsEvent({
              location: 'security-assessment-pre-scan',
              category: 'find-secrets-banner',
              action: 'learn-more',
              tag: 'button',
              group: 'expand',
            })
          },
          label: 'Learn More',
        }}
        images={{
          day: '/images/secret-scanning/risk-assessment/start_scan_banner--day.png',
          night: '/images/secret-scanning/risk-assessment/start_scan_banner--night.png',
        }}
        isLoading={mutation.isPending || isEligibilityLoading}
        analyticsVisible={{
          category: 'find-secrets-banner',
          action: 'visible',
          group: 'expand',
          location: 'security-assessment-pre-scan',
        }}
        showCopilotAssist={showCopilotAssist}
      />
      {isCodeSecurityRiskAssessmentEnabled ? <RiskAssessmentFaq /> : <FAQ />}
      {isDialogOpen && (
        <RunAssessmentDialog
          onClose={() => setIsDialogOpen(false)}
          onStartScan={handleStartScan}
          org={org}
          source={SOURCE}
          eligibility={resolvedEligibility}
        />
      )}
    </>
  )
}

