import {Banner, Checkbox, FormControl} from '@primer/react'

import type {EligibilityResponse} from '../../types'
import styles from './AssessmentSelection.module.css'

function formatCooldownDate(dateString: string): string {
  return new Date(dateString).toLocaleDateString('en-US', {month: 'long', day: 'numeric', year: 'numeric'})
}

interface AssessmentSelectionProps {
  eligibility: EligibilityResponse
  runSra: boolean
  runCsra: boolean
  onRunSraChange: (checked: boolean) => void
  onRunCsraChange: (checked: boolean) => void
  showWarning: boolean
}

export function AssessmentSelection({
  eligibility,
  runSra,
  runCsra,
  onRunSraChange,
  onRunCsraChange,
  showWarning,
}: AssessmentSelectionProps) {
  const sra = eligibility.sra
  const csra = eligibility.csra

  return (
    <div className={styles.Container}>
      {showWarning && (
        <div className={styles.WarningBanner}>
          <Banner variant="warning" title="Selection required" hideTitle>
            Make a selection to continue
          </Banner>
        </div>
      )}
      <div className={styles.Heading}>Run risk assessment for:</div>
      <FormControl disabled={!sra.eligible}>
        <Checkbox checked={runSra} onChange={e => onRunSraChange(e.target.checked)} />
        <FormControl.Label>
          <span className={styles.AssessmentLabel}>Secret Protection</span>
        </FormControl.Label>
        {sra.eligible ? (
          <FormControl.Caption>All repositories included</FormControl.Caption>
        ) : (
          sra.cooldown_ends_at && (
            <FormControl.Caption>
              <span className={styles.CooldownText}>
                Next run available on {formatCooldownDate(sra.cooldown_ends_at)}
              </span>
            </FormControl.Caption>
          )
        )}
      </FormControl>
      {csra && (
        <FormControl disabled={!csra.eligible}>
          <Checkbox checked={runCsra} onChange={e => onRunCsraChange(e.target.checked)} />
          <FormControl.Label>
            <span className={styles.AssessmentLabel}>Code Security</span>
          </FormControl.Label>
          {csra.eligible ? (
            <FormControl.Caption>Select up to 20 repositories with supported languages</FormControl.Caption>
          ) : (
            csra.cooldown_ends_at && (
              <FormControl.Caption>
                <span className={styles.CooldownText}>
                  Next run available on {formatCooldownDate(csra.cooldown_ends_at)}
                </span>
              </FormControl.Caption>
            )
          )}
        </FormControl>
      )}
    </div>
  )
}
