import type {ReactNode} from 'react'
import {useId} from 'react'
import {Radio, RadioGroup} from '@primer/react'
import {RepoIcon, ChecklistIcon} from '@primer/octicons-react'

const REPO_SELECTION = {
  ALL: 'all',
  SELECTED: 'selected',
} as const

export type RepoSelection = (typeof REPO_SELECTION)[keyof typeof REPO_SELECTION]
export {REPO_SELECTION}

interface RadioOptionBoxProps {
  value: string
  checked: boolean
  label: string
  icon: ReactNode
}

function RadioOptionBox({value, checked, label, icon}: RadioOptionBoxProps) {
  const id = useId()

  return (
    <label
      htmlFor={id}
      className="flex-1 tmp-p-3 border rounded-2 d-flex flex-items-center flex-justify-between cursor-pointer"
    >
      <div className="d-flex flex-items-center gap-2">
        <Radio id={id} value={value} checked={checked} />
        <p className="mb-0 text-bold">{label}</p>
      </div>
      {icon}
    </label>
  )
}

interface RepositorySelectionGroupProps {
  value: RepoSelection
  onChange: (value: RepoSelection) => void
}

export function RepositorySelectionGroup({value, onChange}: RepositorySelectionGroupProps) {
  return (
    <RadioGroup
      className="tmp-mb-3"
      name="repo-selection"
      onChange={selectedValue => onChange(selectedValue as RepoSelection)}
    >
      <RadioGroup.Label visuallyHidden>Repository selection</RadioGroup.Label>
      <div className="d-flex gap-3">
        <RadioOptionBox
          value={REPO_SELECTION.ALL}
          checked={value === REPO_SELECTION.ALL}
          label="All repositories"
          icon={<RepoIcon size={16} className="fgColor-muted" />}
        />
        <RadioOptionBox
          value={REPO_SELECTION.SELECTED}
          checked={value === REPO_SELECTION.SELECTED}
          label="Selected repositories"
          icon={<ChecklistIcon size={16} className="fgColor-muted" />}
        />
      </div>
    </RadioGroup>
  )
}
