import {PickerListBody} from '@github-ui/filter-picker'
import {RepoIcon, RepoLockedIcon, OrganizationIcon, AlertIcon, ArchiveIcon} from '@primer/octicons-react'
import type {CsraCostEstimationRepository, EnablementRepo} from '../../types'
import {FormControl, Checkbox, Spinner, Truncate} from '@primer/react'
import {Filter} from '@github-ui/filter'
import type {SubmitEvent, FilterQuery} from '@github-ui/filter-core'
import Pluralize from 'pluralize'
import {Blankslate} from '@primer/react/experimental'
import {useMemo} from 'react'
import styles from './RepositorySelection.module.css'
import {getAllStaticProviders} from '@github-ui/repos-filter/providers'

function isCsraRepo(repo: EnablementRepo): repo is CsraCostEstimationRepository {
  return 'vulnerabilitiesFound' in repo
}

const LoadingState = () => (
  <Blankslate>
    <Blankslate.Visual>
      <Spinner size="medium" />
    </Blankslate.Visual>
    <Blankslate.Description>Loading repositories...</Blankslate.Description>
  </Blankslate>
)

const ErrorState = () => (
  <Blankslate>
    <Blankslate.Visual>
      <AlertIcon className="fgColor-danger" />
    </Blankslate.Visual>
    <Blankslate.Heading>We couldn&apos;t load the repositories</Blankslate.Heading>
    <Blankslate.Description>Try again or if the problem persists contact support.</Blankslate.Description>
  </Blankslate>
)

const EmptyState = () => (
  <Blankslate>
    <Blankslate.Heading>No repositories found</Blankslate.Heading>
    <Blankslate.Description>Use a different query.</Blankslate.Description>
  </Blankslate>
)

interface RepositorySelectionProps {
  reposById: ReadonlyMap<number, EnablementRepo>
  totalRepoCount: number
  selectedRepoIds: Set<number>
  selectedCommitterIds: Set<number>
  isLoading: boolean
  isError: boolean
  onRepositorySelectionChange: (repos: EnablementRepo[]) => void
  filterValue: string
  onFilterChange: (value: string) => void
  onFilterSubmit: (query: FilterQuery, eventType: SubmitEvent) => void
  orgLogin: string
}

export function RepositorySelection({
  reposById,
  totalRepoCount,
  selectedRepoIds,
  onRepositorySelectionChange,
  selectedCommitterIds,
  isLoading,
  isError,
  filterValue,
  onFilterChange,
  onFilterSubmit,
  orgLogin,
}: RepositorySelectionProps) {
  const visibleRepoIds = useMemo(() => {
    if (isLoading || isError) return new Set()
    return new Set(reposById.keys())
  }, [reposById, isLoading, isError])

  const visibleRepos = useMemo(() => {
    if (isLoading || isError) return []
    return Array.from(reposById.values())
  }, [reposById, isLoading, isError])
  const noVisibleRepos = visibleRepos.length === 0
  const selectedRepos = useMemo(() => {
    const memo: EnablementRepo[] = []
    for (const selectedRepoId of selectedRepoIds) {
      const selectedRepo = reposById.get(selectedRepoId)
      if (selectedRepo) memo.push(selectedRepo)
    }
    return memo
  }, [reposById, selectedRepoIds])
  const noSelectedRepos = selectedRepos.length === 0
  const hiddenSelectedCount = useMemo(() => {
    if (isLoading || isError) return 0
    return Array.from(selectedRepoIds).filter(id => !visibleRepoIds.has(id)).length
  }, [visibleRepoIds, selectedRepoIds, isLoading, isError])
  const isSelectAllChecked = useMemo(() => {
    if (noVisibleRepos || noSelectedRepos) return false
    for (const visibleRepo of visibleRepos) {
      if (!selectedRepoIds.has(visibleRepo.id)) return false
    }
    return true
  }, [visibleRepos, noVisibleRepos, selectedRepoIds, noSelectedRepos])

  const isSelectAllIndeterminate = useMemo(() => {
    if (isSelectAllChecked || noVisibleRepos || noSelectedRepos) return false
    for (const visibleRepo of visibleRepos) {
      if (selectedRepoIds.has(visibleRepo.id)) return true
    }
    return false
  }, [isSelectAllChecked, visibleRepos, noVisibleRepos, selectedRepoIds, noSelectedRepos])

  const handleSelectAll = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.checked) {
      onRepositorySelectionChange(visibleRepos)
    } else {
      onRepositorySelectionChange([])
    }
  }

  const providers = useMemo(() => getAllStaticProviders(), [])

  const getBlankView = () => {
    if (isLoading) return <LoadingState />
    if (isError) return <ErrorState />
    if (noVisibleRepos) return <EmptyState />
    return null
  }

  function getRepoIcon(repo: EnablementRepo) {
    if (repo.archived) return <ArchiveIcon size={16} />

    switch (repo.visibility) {
      case 'public':
        return <RepoIcon size={16} />
      case 'private':
        return <RepoLockedIcon size={16} />
      case 'internal':
        return <OrganizationIcon size={16} />
      default:
        return <RepoIcon size={16} />
    }
  }

  function getRepoName(repo: EnablementRepo) {
    return (
      <Truncate title={repo.name} className={`flex-1 text-semibold ${styles.repositoryName}`}>
        {repo.name}
      </Truncate>
    )
  }

  function getFindingsText(repo: EnablementRepo) {
    if (isCsraRepo(repo)) {
      return repo.vulnerabilitiesFound === null
        ? 'Not scanned'
        : Pluralize('vulnerability', repo.vulnerabilitiesFound, true)
    }
    return repo.tokensFound === null ? 'Not scanned' : Pluralize('secret', repo.tokensFound, true)
  }

  function getAdditionalCommitterDescription(repo: EnablementRepo) {
    if (repo.archived || repo.visibility === 'public') return 'Free'
    if (selectedRepoIds.has(repo.id)) return null

    const filteredAdditionalCommitterIds = repo.additionalCommitterIds.filter(id => !selectedCommitterIds.has(id))

    return (
      <span style={{whiteSpace: 'nowrap'}}>
        +{filteredAdditionalCommitterIds.length.toLocaleString()}
        {Pluralize(' committer', filteredAdditionalCommitterIds.length, false)}
      </span>
    )
  }

  return (
    <div className={styles.repositorySelectionContainer}>
      <div className={styles.stickyHeader}>
        <div className="border-bottom tmp-px-3 py-2">
          <Filter
            id="repository-filter"
            label="Filter repositories"
            variant="input"
            filterValue={filterValue}
            onChange={onFilterChange}
            onSubmit={onFilterSubmit}
            providers={providers}
            context={{org: orgLogin}}
            aria-label="Filter repositories using available filters"
            aria-describedby="filter-help-text"
          />
          <div id="filter-help-text" className="sr-only">
            Filter repositories using text search or available filters
          </div>
        </div>
        {!noVisibleRepos && (
          <FormControl className="bgColor-inset border-bottom d-flex tmp-px-3 py-2">
            <Checkbox
              checked={isSelectAllChecked}
              indeterminate={isSelectAllIndeterminate}
              onChange={handleSelectAll}
            />
            <FormControl.Label>Select all</FormControl.Label>
          </FormControl>
        )}
      </div>
      <div className={styles.repositoryListContainer}>
        <PickerListBody
          hiddenSelectedCount={hiddenSelectedCount}
          isFiltered={hiddenSelectedCount > 0}
          blankMessage={getBlankView()}
          totalItemsCount={totalRepoCount}
          selectionVariant="multiple"
          items={visibleRepos}
          selectedItems={selectedRepos}
          setSelectedItems={onRepositorySelectionChange}
          title="Select repositories"
          onRenderItemName={getRepoName}
          onRenderItemLeadingVisual={getRepoIcon}
          onRenderItemTrailingVisual={getFindingsText}
          onRenderItemDescription={getAdditionalCommitterDescription}
        />
      </div>
    </div>
  )
}
