import {publishOpenCopilotChat} from '@github-ui/copilot-chat/utils/copilot-chat-events'
import {CopilotChatIntents} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {sendEvent} from '@github-ui/hydro-analytics'

export const SECURITY_ASSESSMENT_COPILOT_CHAT_ID = 'copilot-security-assessment'

export function openSecurityAssessmentCopilotChat() {
  sendEvent('copilot.open_copilot_chat', {source: `element ${SECURITY_ASSESSMENT_COPILOT_CHAT_ID}`})
  publishOpenCopilotChat({
    id: SECURITY_ASSESSMENT_COPILOT_CHAT_ID,
    intent: CopilotChatIntents.conversation,
    newThread: true,
    references: [],
    suggestionsContext: 'security-assessment',
    customInstructions: {
      type: 'Assistant',
      owner: '',
      prompt:
        'You are a security-focused assistant specializing in secret risk assessment. ' +
        'Help the user understand and mitigate risks related to exposed secrets, leaked credentials, ' +
        'and secret scanning findings. Focus on prioritizing remediation, explaining risk severity, ' +
        'and recommending best practices for secret management.',
    },
  })
}
