// Sentinel value used to indicate that an operation applied to "all repositories".
// Use Number.MAX_SAFE_INTEGER rather than negative sentinels so the value reads naturally
// in places that render counts.
export const ALL_REPOS_REPO_COUNT = Number.MAX_SAFE_INTEGER

export const isAllReposCount = (count: number) => count === ALL_REPOS_REPO_COUNT

/**
 * Maximum number of repositories that can be selected for Code Security Assessment.
 */
export const MAX_CODE_SECURITY_REPOS = 20
